        return str(_m.get("parse_engine") or "")
    if isinstance(_m, str):
        try:
            _d = json.loads(_m)
            return str(_d.get("parse_engine") or "") if isinstance(_d, dict) else ""
        except Exception:
            return ""
    return ""


