            or (0x2200 <= _o <= 0x22FF)  # 数学运算符 ≈≤≥≠…
            or (0x2500 <= _o <= 0x257F)  # 盒绘线 ╓╞╢╚┴│╠╣└┼…
            or (0x2580 <= _o <= 0x259F)  # 块状 ▄▀█…
        ):
            _bad += 1
            if len(_bad_chars) < 8:
                _bad_chars.append(_c)
