    if _metrics["empty_conversion"]:
        _attr.append({"dim": "doc", "cause": f"{_metrics['empty_conversion']} 个文档解析成功但无文本 → 空文档/纯图片/扫描件未走 OCR",
                      "suggestion": "确认文档含可提取文本；图片型 PDF 需 OCR 支持"})
    if _garbled_n:
